CREATE PROCEDURE OrderProduct(
    IN CustomerID INT,
    IN ProductID INT,
    IN QuantityOrdered INT
)
BEGIN
    DECLARE ProductFound BOOLEAN;

    -- Проверяем наличие товара
    SELECT COUNT(*) INTO ProductFound
    FROM Products
    WHERE ProductID = ProductID;

    -- Если товар не найден, выбрасываем исключение
    IF ProductFound = 0 THEN
    -- (1)
        ROLLBACK;
    ELSE
        -- Уменьшаем количество товара на складе
        UPDATE Products SET Quantity = Quantity - QuantityOrdered
        WHERE ProductID = ProductID;

        -- Добавляем запись о заказе
        INSERT INTO Orders (OrderID, CustomerID, ProductID, QuantityOrdered)
        VALUES
            (NULL, CustomerID, ProductID, QuantityOrdered);
    END IF;

    IF (CustomerID > 100) THEN
       ROLLBACK;
    END IF;

    COMMIT;
END//
DELIMITER ;

