class MemoryManager {
    constructor(maxSize) {
        this.maxSize = maxSize;
        this.cache = new Map();
        this.currentSize = 0;
    }

    add(key, value) {
        const size = JSON.stringify(value).length;
        this.currentSize += size;
        this.cache.set(key, value);
    }

    get(key) {
        return this.cache.get(key);
    }
}

